def transform(grid):
    h, w = len(grid), len(grid[0])

    # Full-width and full-height lines mark the boundaries between regions.
    hbars = [r for r in range(h) if len(set(grid[r])) == 1]
    vbars = [c for c in range(w) if len({grid[r][c] for r in range(h)}) == 1]

    def spans(size, bars):
        result = []
        start = 0
        for b in bars:
            if start < b:
                result.append((start, b))
            start = b + 1
        if start < size:
            result.append((start, size))
        return result

    rows = spans(h, hbars)
    cols = spans(w, vbars)

    out = []
    for r0, r1 in rows:
        line = []
        for c0, c1 in cols:
            count = sum(grid[r][c] == 5
                        for r in range(r0, r1)
                        for c in range(c0, c1))
            line.append(1 if count == 2 else 3)
        out.append(line)
    return out
